for f in EAS:
    if not ida_funcs.get_func(f): continue
    for h in idautils.FuncItems(f):
        if idc.print_insn_mnem(h)!='call' or idc.get_operand_type(h,0) in (6,7): continue
        t=ida_typeinf.tinfo_t()
        if not ida_nalt.get_op_tinfo(t,h,0): continue
        fd=ida_typeinf.func_type_data_t()
        if not t.get_func_details(fd): continue
        n=sum(1 for a in fd if not a.argloc.is_reg1() and not a.argloc.is_reg2())
        cc=fd.cc & ida_typeinf.CM_CC_MASK
        exp=0 if cc==ida_typeinf.CM_CC_CDECL else 4*n
        purge=idc.get_spd(idc.next_head(h))-idc.get_spd(h)
        if exp!=purge: bad.append((hex(f),hex(h),str(t),purge))
result={'n':len(bad),'bad':bad[:80]}
